# 聚类：按「金属性得分」给元素分组
# 得分高=活泼金属，低=非金属，几乎为 0=稀有气体
na = 8      # 钠：见到水就炸的活泼金属
mg = 6      # 镁：温和的金属
al = 5      # 铝：常见轻金属
s = 2       # 硫：黄色非金属
cl = 1      # 氯：活泼非金属
he = 0      # 氦：懒得反应的稀有气体

t = 3.5     # 分界线：得分 > 3.5 归金属组

costume("🧬")
say("性质分界线 t=" + t + "，开始聚类！")

if na > t:
    say("钠(8) → 金属组")
else:
    say("钠(8) → 非金属组")

if mg > t:
    say("镁(6) → 金属组")
else:
    say("镁(6) → 非金属组")

if al > t:
    say("铝(5) → 金属组")
else:
    say("铝(5) → 非金属组")

if s > t:
    say("硫(2) → 金属组")
else:
    say("硫(2) → 非金属组")

if cl > t:
    say("氯(1) → 金属组")
else:
    say("氯(1) → 非金属组")

if he > t:
    say("氦(0) → 金属组")
else:
    say("氦(0) → 非金属组")

say("6 个元素分成两组！周期表同族元素，就是性质聚到一类的元素")
